'use strict';

/**
* Split a 64-bit signed integer into a higher order word (32-bit unsigned integer) and a lower order word (32-bit unsigned integer).
*
* @module @stdlib/number-int64-base-to-words
*
* @example
* import Int64 from '@stdlib/number-int64-ctor';
* import toWords from '@stdlib/number-int64-base-to-words';
*
* var a = new Int64( 4294967296 );
* var w = toWords( a );
* // returns [ 1, 0 ]
*
* @example
* import Uint32Array from '@stdlib/array-uint32';
* import Int64 from '@stdlib/number-int64-ctor';
* import toWords from '@stdlib/number-int64-base-to-words';
*
* var out = new Uint32Array( 2 );
*
* var a = new Int64( 4294967296 );
* var w = toWords.assign( a, out, 1, 0 );
* // returns <Uint32Array>[ 1, 0 ]
*
* var bool = ( w === out );
* // returns true
*/

// MODULES //

import setReadOnly from '@stdlib/utils-define-nonenumerable-read-only-property';
import main from './main.js';
import assign from './assign.js';


// MAIN //

setReadOnly( main, 'assign', assign );


// EXPORTS //

export default main;
